// Decodificar base64 a binary y preparar para subir a Gemini Files API

const base64Data = $input.first().json.pdf_base64;
const apiKey = $input.first().json.api_key;
const rubrica = $input.first().json.rubrica;
const contexto = $input.first().json.contexto;

if (!base64Data || !apiKey) {
  throw new Error('Faltan datos requeridos: pdf_base64 y api_key');
}

if (!rubrica || !rubrica.criterios) {
  throw new Error('Faltan datos requeridos: rubrica con criterios');
}

// Decodificar base64 a buffer binario
const buffer = Buffer.from(base64Data, 'base64');

return [{
  json: {
    api_key: apiKey,
    rubrica: rubrica,
    contexto: contexto
  },
  binary: {
    pdf: {
      data: buffer.toString('base64'),
      mimeType: 'application/pdf',
      fileName: `entrega_${contexto?.alumno?.replace(/\s+/g, '_') || 'alumno'}.pdf`
    }
  }
}];

// Construir body para Gemini generateContent con el PDF subido y prompt de corrección

const uploadResponse = $input.first().json;
const apiKey = $('Decodificar PDF').first().json.api_key;
const rubrica = $('Decodificar PDF').first().json.rubrica;
const contexto = $('Decodificar PDF').first().json.contexto;

// Verificar si hubo error en upload
if (uploadResponse.error) {
  throw new Error(`Error al subir PDF a Gemini: ${JSON.stringify(uploadResponse.error)}`);
}

const fileUri = uploadResponse.file?.uri;
if (!fileUri) {
  throw new Error('No se obtuvo URI del archivo subido a Gemini');
}

// Construir lista de criterios para el prompt
let criteriosTexto = '';
for (const criterio of rubrica.criterios) {
  const puntajeMax = criterio.puntaje_maximo || criterio.peso || 0;
  criteriosTexto += `- ${criterio.nombre} (${puntajeMax} pts): ${criterio.descripcion || ''}\n`;
  if (criterio.subcriterios && criterio.subcriterios.length > 0) {
    for (const sub of criterio.subcriterios) {
      criteriosTexto += `  * ${sub.descripcion}\n`;
    }
  }
}

// Construir lista de penalizaciones si existen
let penalizacionesTexto = '';
if (rubrica.penalizaciones && rubrica.penalizaciones.length > 0) {
  penalizacionesTexto = '\n## PENALIZACIONES\n';
  for (const p of rubrica.penalizaciones) {
    penalizacionesTexto += `- ${p.descripcion}: -${p.descuento_porcentaje}%\n`;
  }
}

// Construir condiciones de desaprobación si existen
let condicionesTexto = '';
if (rubrica.condiciones_desaprobacion && rubrica.condiciones_desaprobacion.length > 0) {
  condicionesTexto = '\n## CONDICIONES DE DESAPROBACIÓN AUTOMÁTICA\n';
  for (const c of rubrica.condiciones_desaprobacion) {
    condicionesTexto += `- Si: ${c.condicion} → Nota final: ${c.nota_final}\n`;
  }
}

// Prompt especializado para corrección de entregas PDF (ejercicios físicos, matemáticos, etc.)
const prompt = `Eres un evaluador académico experto en la materia "${contexto?.materia || 'sin especificar'}".

Tu tarea es evaluar la resolución de ejercicios del alumno "${contexto?.alumno || 'sin especificar'}" a partir del PDF adjunto, según la rúbrica proporcionada.

El PDF puede contener:
- Ejercicios resueltos a mano (escritura, fórmulas, cálculos, gráficos)
- Resoluciones escaneadas o fotografiadas
- Cualquier tipo de trabajo práctico en formato documento

Lee e interpreta TODO el contenido visual del PDF con atención.

## RÚBRICA DE EVALUACIÓN

Título: ${rubrica.titulo || 'Sin título'}
Descripción: ${rubrica.descripcion || ''}
Tipo: ${rubrica.tipo || 'TP'}
Puntaje máximo: ${rubrica.puntaje_maximo || 100}

Criterios a evaluar:
${criteriosTexto}${penalizacionesTexto}${condicionesTexto}

## INSTRUCCIONES DE EVALUACIÓN

Para cada criterio de la rúbrica:
1. Analiza detenidamente el contenido del PDF relacionado con ese criterio
2. Asigna un puntaje entre 0 y el máximo del criterio
3. Determina el estado:
   - "OK" si logra ≥80% del puntaje máximo del criterio
   - "WARNING" si logra 40-79% del puntaje máximo
   - "ERROR" si logra <40% del puntaje máximo
4. Proporciona feedback específico basado en lo que ves en el PDF

Además:
- Lista 2-4 fortalezas de la resolución (array de strings)
- Lista 2-4 recomendaciones de mejora específicas (array de strings)
- Escribe un comentario general de 2-3 oraciones sobre la calidad global del trabajo

## FORMATO DE RESPUESTA OBLIGATORIO

Responde ÚNICAMENTE con un JSON válido con esta estructura exacta:

{
  "nota": <número entre 0 y ${rubrica.puntaje_maximo || 100}>,
  "criterios": [
    {
      "nombre": "<nombre exacto del criterio de la rúbrica>",
      "puntaje_obtenido": <número>,
      "puntaje_maximo": <número>,
      "estado": "<OK|WARNING|ERROR>",
      "feedback": "<feedback específico basado en lo observado en el PDF>"
    }
  ],
  "fortalezas": ["<fortaleza 1>", "<fortaleza 2>"],
  "recomendaciones": ["<recomendación 1>", "<recomendación 2>"],
  "comentario_general": "<comentario de 2-3 oraciones>"
}

IMPORTANTE:
- La suma de puntaje_obtenido de todos los criterios debe ser igual a "nota"
- Cada criterio de la rúbrica debe aparecer en la respuesta
- El estado debe calcularse correctamente según el porcentaje del criterio individual
- NO incluyas texto antes o después del JSON
- NO uses markdown code blocks, solo JSON puro`;

// Construir body para Gemini API con el PDF referenciado por URI
const body = {
  generationConfig: {
    temperature: 0,
    topK: 1,
    topP: 1,
    candidateCount: 1,
    responseMimeType: "application/json",
    responseSchema: {
      type: "object",
      properties: {
        nota: { type: "number" },
        criterios: {
          type: "array",
          items: {
            type: "object",
            properties: {
              nombre: { type: "string" },
              puntaje_obtenido: { type: "number" },
              puntaje_maximo: { type: "number" },
              estado: { type: "string", enum: ["OK", "WARNING", "ERROR"] },
              feedback: { type: "string" }
            },
            required: ["nombre", "puntaje_obtenido", "puntaje_maximo", "estado", "feedback"]
          }
        },
        fortalezas: {
          type: "array",
          items: { type: "string" }
        },
        recomendaciones: {
          type: "array",
          items: { type: "string" }
        },
        comentario_general: { type: "string" }
      },
      required: ["nota", "criterios", "fortalezas", "recomendaciones", "comentario_general"]
    }
  },
  contents: [
    {
      role: "user",
      parts: [
        {
          fileData: {
            fileUri: fileUri,
            mimeType: "application/pdf"
          }
        },
        {
          text: prompt
        }
      ]
    }
  ]
};

return [{ json: { geminiBody: body, api_key: apiKey } }];

// Parser de respuesta de Gemini para corrección PDF
// Mismo patrón que correccion-workflow.json

const geminiResponse = $input.first().json;
const startTime = Date.now();

try {
  // Verificar si hay error de Gemini (503, 429, 500, etc.)
  if (geminiResponse.error) {
    const errorMsg = geminiResponse.error.message || JSON.stringify(geminiResponse.error);
    const errorCode = geminiResponse.error.code || 'UNKNOWN';

    return [{
      json: {
        success: false,
        error: {
          code: 'GEMINI_ERROR',
          message: `Error de Gemini [${errorCode}]: ${errorMsg}`,
          retry: errorCode === 503 || errorCode === 500
        }
      }
    }];
  }

  // Normalizar respuesta (puede venir como array o objeto)
  let responseArray;
  if (Array.isArray(geminiResponse)) {
    responseArray = geminiResponse;
  } else if (geminiResponse.body && Array.isArray(geminiResponse.body)) {
    responseArray = geminiResponse.body;
  } else if (geminiResponse.data && Array.isArray(geminiResponse.data)) {
    responseArray = geminiResponse.data;
  } else {
    responseArray = [geminiResponse];
  }

  const candidate = responseArray[0]?.candidates?.[0];

  if (!candidate) {
    return [{
      json: {
        success: false,
        error: {
          code: 'PARSING_ERROR',
          message: 'No se encontró candidate en respuesta de Gemini',
          retry: true
        }
      }
    }];
  }

  const textContent = candidate.content?.parts?.[0]?.text;

  if (!textContent) {
    return [{
      json: {
        success: false,
        error: {
          code: 'PARSING_ERROR',
          message: 'No se encontró texto en la respuesta',
          retry: true
        }
      }
    }];
  }

  // Parsear el JSON (responseMimeType: application/json garantiza JSON puro)
  const parsedData = JSON.parse(textContent);

  // Validar estructura mínima
  if (!parsedData.nota && parsedData.nota !== 0) {
    return [{
      json: {
        success: false,
        error: {
          code: 'PARSING_ERROR',
          message: "Respuesta no contiene campo 'nota'",
          retry: true
        }
      }
    }];
  }

  if (!Array.isArray(parsedData.criterios)) {
    return [{
      json: {
        success: false,
        error: {
          code: 'PARSING_ERROR',
          message: "Respuesta no contiene 'criterios' como array",
          retry: true
        }
      }
    }];
  }

  // Construir metadata
  const elapsedTime = Date.now() - startTime;
  const metadata = {
    modelo: 'gemini-2.5-flash',
    modo: 'vision-pdf',
    tokens_entrada: candidate.tokenCount?.totalTokens || 0,
    tokens_salida: candidate.tokenCount?.candidatesTokenCount || 0,
    tiempo_ms: elapsedTime
  };

  // Retornar resultado exitoso — mismo contrato que correccion-workflow.json
  return [{
    json: {
      success: true,
      correccion: {
        nota: parsedData.nota,
        criterios: parsedData.criterios,
        fortalezas: parsedData.fortalezas || [],
        recomendaciones: parsedData.recomendaciones || [],
        comentario_general: parsedData.comentario_general || ''
      },
      metadata: metadata
    }
  }];

} catch (error) {
  return [{
    json: {
      success: false,
      error: {
        code: 'PARSING_ERROR',
        message: `Error al procesar corrección PDF: ${error.message}`,
        retry: true
      }
    }
  }];
}
